package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingIndex_TriageGen1Test {

    @Test
    public void testSiblingIndex_FirstSibling() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p></div>");
        Node firstP = doc.select("p").get(0);
        Node secondP = doc.select("p").get(1);

        Assert.assertEquals(0, firstP.siblingIndex());
        Assert.assertEquals(1, secondP.siblingIndex());
    }

    @Test
    public void testSiblingIndex_MiddleSibling() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p><p>3</p></div>");
        List<Node> ps = doc.select("p");

        Assert.assertEquals(0, ps.get(0).siblingIndex());
        Assert.assertEquals(1, ps.get(1).siblingIndex());
        Assert.assertEquals(2, ps.get(2).siblingIndex());
    }

    @Test
    public void testSiblingIndex_SingleChild() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p></div>");
        Node p = doc.select("p").get(0);

        Assert.assertEquals(0, p.siblingIndex());
    }

    @Test
    public void testSiblingIndex_RootNode() {
        // A document node or a node without a parent typically has a sibling index of 0 
        // or is treated as the only node in its scope.
        Document doc = Parser.parseBodyFragment("<div></div>");
        Node html = doc.childNode(0); // The <html> node

        Assert.assertEquals(0, html.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterManipulation() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p><p>3</p></div>");
        Node p1 = doc.select("p").get(0);
        Node p2 = doc.select("p").get(1);
        Node p3 = doc.select("p").get(2);

        // Remove the middle one
        p2.remove();

        // Now p3 should be at index 1
        Assert.assertEquals(0, p1.siblingIndex());
        Assert.assertEquals(1, p3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WithDifferentParentTypes() {
        Document doc = Parser.parseBodyFragment("<ul><li>1</li><li>2</li></ul>");
        Node ul = doc.select("ul").get(0);
        Node li1 = ul.childNode(0);
        Node li2 = ul.childNode(1);

        Assert.assertEquals(0, li1.siblingIndex());
        Assert.assertEquals(1, li2.siblingIndex());
    }
}
